#include "stdlib/math/base/special/kernel_log1pf.h"
#include <stdint.h>

/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: polyval_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_p( const float x ) {
	return 0.40000972152 + (x * 0.24279078841);
}

// END: polyval_p

// BEGIN: polyval_q

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float polyval_q( const float x ) {
	return 0.66666662693 + (x * 0.28498786688);
}

// END: polyval_q

/* End auto-generated functions. */

/**
* Computes `logf(1+f) - f` for `1+f` in `~[sqrtf(2)/2, sqrtf(2)]`.
*
* @param f    input value
* @return     output value
*
* @example
* double out = stdlib_base_kernel_log1p( 1.0 );
* // returns ~0.1931
*/
float stdlib_base_kernel_log1pf( const float f ) {
	float hfsq;
	float t1;
	float t2;
	float R;
	float s;
	float z;
	float w;

	s = f / ( 2.0f + f );
	z = s * s;
	w = z * z;
	t1 = w * polyval_p( w );
	t2 = z * polyval_q( w );
	R = t2 + t1;
	hfsq = 0.5f * f * f;
	return s * ( hfsq + R );
}
